29	export default async function Findings({
30	  searchParams,
31	}: {
32	  searchParams: Promise<SearchParamsProps>;
33	}) {
34	  const resolvedSearchParams = await searchParams;
35	  const { encodedSort } = extractSortAndKey(resolvedSearchParams);
36	  const { filters, query } = extractFiltersAndQuery(resolvedSearchParams);
37	
38	  const [providersData, scansData] = await Promise.all([
39	    getProviders({ pageSize: 50 }),
40	    getScans({ pageSize: 50 }),
41	  ]);
42	
43	  const filtersWithScanDates = applyDefaultMutedFilter(
44	    await resolveFindingScanDateFilters({
45	      filters,
46	      scans: scansData?.data || [],
47	      loadScan: async (scanId: string) => {
48	        const response = await getScan(scanId);
49	        return response?.data;
50	      },
51	    }),
52	  );
53	
54	  const hasHistoricalData = hasDateOrScanFilter(filtersWithScanDates);
55	
56	  const metadataInfoData = await (
57	    hasHistoricalData ? getMetadataInfo : getLatestMetadataInfo
58	  )({
59	    query,
60	    sort: encodedSort,
61	    filters: filtersWithScanDates,
62	  });
63	
64	  // Extract unique regions, services, categories, groups from the new endpoint
65	  const uniqueRegions = metadataInfoData?.data?.attributes?.regions || [];
66	  const uniqueServices = metadataInfoData?.data?.attributes?.services || [];
67	  const uniqueResourceTypes =
68	    metadataInfoData?.data?.attributes?.resource_types || [];
69	  const uniqueCategories = metadataInfoData?.data?.attributes?.categories || [];
70	  const uniqueGroups = metadataInfoData?.data?.attributes?.groups || [];
71	
72	  // Extract scan UUIDs with "completed" state and more than one resource
73	  const completedScans = scansData?.data?.filter(
74	    (scan: ScanProps) =>
75	      scan.attributes.state === "completed" &&
76	      scan.attributes.unique_resource_count > 1,
77	  );
78	
79	  const completedScanIds =
80	    completedScans?.map((scan: ScanProps) => scan.id) || [];
81	
82	  const scanDetails = createScanDetailsMapping(
83	    completedScans || [],
84	    providersData,
85	  ) as { [uid: string]: ScanEntity }[];
86	
87	  return (
88	    <ContentLayout title="Findings" icon="lucide:tag">
89	      <FilterTransitionWrapper>
90	        <div className="mb-6">
91	          <FindingsFilters
92	            providers={providersData?.data || []}
93	            completedScanIds={completedScanIds}
94	            scanDetails={scanDetails}
95	            uniqueRegions={uniqueRegions}
96	            uniqueServices={uniqueServices}
97	            uniqueResourceTypes={uniqueResourceTypes}
98	            uniqueCategories={uniqueCategories}
99	            uniqueGroups={uniqueGroups}
100	          />
101	        </div>
102	        <Suspense fallback={<SkeletonTableFindings />}>
103	          <SSRDataTable
104	            searchParams={resolvedSearchParams}
105	            filters={filtersWithScanDates}
106	          />
107	        </Suspense>
108	      </FilterTransitionWrapper>
109	    </ContentLayout>
110	  );
111	}
112	
113	const SSRDataTable = async ({
114	  searchParams,
115	  filters,
116	}: {
117	  searchParams: SearchParamsProps;
118	  filters: Record<string, string>;
119	}) => {
120	  const page = parseInt(searchParams.page?.toString() || "1", 10);
121	  const pageSize = parseInt(searchParams.pageSize?.toString() || "10", 10);
122	
123	  const { encodedSort } = extractSortAndKey(searchParams);
124	  const hasHistoricalData = hasDateOrScanFilter(filters);
125	
126	  const fetchFindingGroups = hasHistoricalData
127	    ? getFindingGroups
128	    : getLatestFindingGroups;
129	
130	  const findingGroupsData = await fetchFindingGroups({
131	    page,
132	    ...(encodedSort && { sort: encodedSort }),
133	    filters,
134	    pageSize,
135	  });
136	
137	  // Transform API response to FindingGroupRow[]
138	  const groups = adaptFindingGroupsResponse(findingGroupsData);
139	  // Key resets all client state (selection, drill-down) when data changes
140	  const groupKey = groups.map((g) => g.id).join(",");
141	
142	  return (
143	    <>
144	      {findingGroupsData?.errors?.length > 0 && (
145	        <div className="text-small mb-4 flex rounded-lg border border-red-500 bg-red-100 p-2 text-red-700">
146	          <p className="mr-2 font-semibold">Error:</p>
147	          <p>{findingGroupsData.errors[0].detail}</p>
148	        </div>
149	      )}
150	      <FindingsGroupTable
151	        key={groupKey}
152	        data={groups}
153	        metadata={findingGroupsData?.meta}
154	        resolvedFilters={filters}
155	        hasHistoricalData={hasHistoricalData}
156	      />
157	    </>
158	  );
159	};
