40	export function useFindingGroupResourceState({
41	  group,
42	  filters,
43	  hasHistoricalData,
44	  onResourceSelectionChange,
45	  scrollContainerRef,
46	}: UseFindingGroupResourceStateOptions): UseFindingGroupResourceStateReturn {
47	  const [rowSelection, setRowSelection] = useState<RowSelectionState>({});
48	  const [resources, setResources] = useState<FindingResourceRow[]>([]);
49	  const [isLoading, setIsLoading] = useState(true);
50	
51	  const handleSetResources = (
52	    newResources: FindingResourceRow[],
53	    _hasMore: boolean,
54	  ) => {
55	    setResources(newResources);
56	    setIsLoading(false);
57	  };
58	
59	  const handleAppendResources = (
60	    newResources: FindingResourceRow[],
61	    _hasMore: boolean,
62	  ) => {
63	    setResources((prev) => [...prev, ...newResources]);
64	    setIsLoading(false);
65	  };
66	
67	  const handleSetLoading = (loading: boolean) => {
68	    setIsLoading(loading);
69	  };
