 * Shared sort tokens for the findings surfaces.
 *
 * Two distinct families exist because the two backends order results
 * differently:
 *
 * - **Family A — plain findings.** The findings API sorts on Postgres ENUM
 *   columns whose ascending order already places FAIL/critical first, so
 *   `status` and `severity` tokens must NOT carry a minus prefix.
 * - **Family B — finding-groups.** The grouped API sorts on integer-weighted
 *   computed columns where descending order is what surfaces
 *   FAIL/critical/new results first, so `status`, `severity` and `delta`
 *   tokens must ALWAYS carry a minus prefix.
 *
 * Centralising the tokens keeps action and component code from re-deriving
 * these prefixes (and getting them subtly wrong) surface by surface.
 */

// ---------------------------------------------------------------------------
// Family A — plain findings (Postgres ENUM, ascending = FAIL/critical first)
// ---------------------------------------------------------------------------

/** Ascending `status`: FAIL comes first in the ENUM order. */
export const FINDINGS_FAIL_FIRST = "status";
/** Ascending `severity`: critical comes first in the ENUM order. */
export const FINDINGS_SEVERITY_HIGH_FIRST = "severity";
/** Most recently inserted findings first. */
export const FINDINGS_RECENT_INSERT = "-inserted_at";
/** Most recently updated findings first (latest-findings endpoint). */
export const FINDINGS_RECENT_UPDATE = "-updated_at";

// ---------------------------------------------------------------------------
// Family B — finding-groups (integer-weighted columns, descending = first)
// ---------------------------------------------------------------------------

/** Descending `status`: FAIL-weighted groups first. */
export const FG_FAIL_FIRST = "-status";
/** Descending `severity`: critical-weighted groups first. */
export const FG_SEVERITY_HIGH_FIRST = "-severity";
/** Descending `delta`: new results first. */
export const FG_DELTA_NEW_FIRST = "-delta";
/** Most recently seen groups first. */
export const FG_RECENT_LAST_SEEN = "-last_seen_at";

// ---------------------------------------------------------------------------
// Composition helper
// ---------------------------------------------------------------------------

/**
 * Joins sort token strings with commas in the order given. The leftmost token
 * has the highest sort precedence (JSON:API rule). Returns an empty string
 * when called with no arguments.
 */
export function composeSort(...tokens: string[]): string {
  return tokens.join(",");
}

// ---------------------------------------------------------------------------
// Preset composite sort strings — Family A (plain findings)
// ---------------------------------------------------------------------------

/**
 * Default sort for the plain findings list. No `delta` (plain findings do not
 * expose that field); `status`/`severity` are un-prefixed (Family A).
 */
export const FINDINGS_DEFAULT_SORT = composeSort(
  FINDINGS_FAIL_FIRST,
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_INSERT,
);

/**
 * Sort used when the API call already applies a `filter[status]`, so `status`
 * is omitted from the sort.
 */
export const FINDINGS_FILTERED_SORT = composeSort(
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_INSERT,
);

/**
 * Sort for the "other findings" list in the resource drawer. Uses
 * `updated_at` because the latest-findings endpoint exposes it.
 */
export const RESOURCE_DRAWER_OTHER_FINDINGS_SORT = composeSort(
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_UPDATE,
);

// ---------------------------------------------------------------------------
// Preset composite sort strings — Family B (finding-groups)
// ---------------------------------------------------------------------------

/** Default sort for the finding-groups list. */
export const FINDING_GROUPS_DEFAULT_SORT = composeSort(
  FG_FAIL_FIRST,
  FG_SEVERITY_HIGH_FIRST,
  FG_DELTA_NEW_FIRST,
  FG_RECENT_LAST_SEEN,
);

/** Default sort for the finding-group resources drill-down (same shape). */
export const FINDING_GROUP_RESOURCES_DEFAULT_SORT = composeSort(
  FG_FAIL_FIRST,
  FG_SEVERITY_HIGH_FIRST,
  FG_DELTA_NEW_FIRST,
  FG_RECENT_LAST_SEEN,
);

/**
 * Sort used when a status filter is already applied on the grouped API.
 * Omits `status` and `delta`; must NOT contain `inserted_at`, which is not a
 * valid sort parameter on the grouped API and causes a backend error.
 */
export const FINDING_GROUPS_FILTERED_SORT = composeSort(
  FG_SEVERITY_HIGH_FIRST,
  FG_RECENT_LAST_SEEN,
);
