/** Wire-format value the API expects for the FAIL status filter. */
export const FAIL_FILTER_VALUE = "FAIL";

/** Wire-format value the API expects for the "new" delta filter. */
export const NEW_DELTA_FILTER_VALUE = "new";

/**
 * Mutates the supplied `URLSearchParams` in place so that only non-muted
 * failing findings are returned: sets `filter[status__in]` to `"FAIL"` and
 * `filter[muted]` to `"false"`, overwriting any pre-existing values for those
 * keys. All other params are left untouched. Returns nothing.
 */
export function applyFailNonMutedFilters(params: URLSearchParams): void {
  params.set("filter[status__in]", FAIL_FILTER_VALUE);
  params.set("filter[muted]", MUTED_FILTER.EXCLUDE);
