/**
 * Normalises a filter value into a flat array of non-empty trimmed tokens.
 *
 * Returns `[]` for `undefined`, splits a single string on commas, flattens an
 * array input by splitting every element on commas, and drops any token that
 * is empty after trimming (so stray or trailing commas produce no entry).
 */
export function splitCsvFilterValues(
  value: string | string[] | undefined,
): string[] {
  if (Array.isArray(value)) {
    return value
      .flatMap((item) => item.split(","))
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return value
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }

  return [];
